diff --git a/lib/features/entries/presentation/cubit/entry_detail_cubit.dart b/lib/features/entries/presentation/cubit/entry_detail_cubit.dart
new file mode 100644
index 0000000..8da2a50
--- /dev/null
+++ b/lib/features/entries/presentation/cubit/entry_detail_cubit.dart
@@ -0,0 +1,117 @@
+import 'dart:async';
+
+import 'package:flutter_bloc/flutter_bloc.dart';
+
+import '../../../../core/failure/failure.dart';
+import '../../../auth/domain/entities/session_status.dart';
+import '../../../auth/domain/repositories/session_repository.dart';
+import '../../domain/entities/pending_entry_write.dart';
+import '../../domain/entities/sync_badge_state.dart';
+import '../../domain/repositories/entries_repository.dart';
+import '../../domain/services/pending_entry_write_tracker.dart';
+import 'entry_detail_state.dart';
+
+/// Drives `EntryDetailScreen` (spec-4-4) — the Boundaries' three-source
+/// composition, merged only here (AD-7: "it never imports/reaches into
+/// `MeusRegistrosCubit` or any other Cubit"):
+/// [SessionRepository.statusStream] (auth status — this cubit is the one
+/// documented compose point the Acceptance Criteria's third bullet names,
+/// even though nothing this screen renders branches on it today:
+/// `ExpiryOverlayHost`'s own independent subscription to the same stream,
+/// unchanged, is still what actually shows the session-expired overlay
+/// above this screen, Boundaries: "no new overlay"), [PendingEntryWrite
+/// Tracker.pendingWrites] feeding the one shared `deriveSyncBadgeState()`
+/// (never recomputed inline), and one [EntriesRepository.getById] fetch
+/// per [load] call.
+///
+/// A DI `factory` (Code Map) — unlike `MeusRegistrosCubit`'s
+/// `lazySingleton`, a fresh instance per visit to `/meus-registros/:id`
+/// matches this screen's single-fetch, throwaway lifecycle, mirroring the
+/// capture cubits' own factory shape (`capture_injection.dart`).
+class EntryDetailCubit extends Cubit<EntryDetailState> {
+  EntryDetailCubit(this._repository, this._tracker, this._sessionRepository)
+    : super(const EntryDetailLoading()) {
+    _pendingSubscription = _tracker.pendingWrites.listen(
+      (writes) => _pendingWrites = writes,
+    );
+    _sessionSubscription = _sessionRepository.statusStream.listen(
+      (status) => _sessionStatus = status,
+    );
+  }
+
+  final EntriesRepository _repository;
+  final PendingEntryWriteTracker _tracker;
+  final SessionRepository _sessionRepository;
+
+  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
+  late final StreamSubscription<SessionStatus> _sessionSubscription;
+
+  /// Mirrors `MeusRegistrosCubit`'s own field of the same name — the
+  /// tracker's latest snapshot, read synchronously by [load]'s own badge
+  /// derivation rather than awaiting a fresh stream value.
+  List<PendingEntryWrite> _pendingWrites = const [];
+
+  /// The latest [SessionStatus] this cubit has observed off the composed
+  /// [SessionRepository.statusStream] — exposed purely so a test can
+  /// assert this cubit (not `EntryDetailScreen` itself) is the one
+  /// composition point for auth status alongside Entry/badge data
+  /// (Acceptance Criteria's third bullet, AD-7); never read by
+  /// `EntryDetailScreen`, which renders only from [state].
+  SessionStatus? get sessionStatus => _sessionStatus;
+  SessionStatus? _sessionStatus;
+
+  /// Guards a stale in-flight [load] call's result landing after a newer
+  /// one (e.g. a quick back-then-forward re-navigation) — same rationale
+  /// and shape as `MeusRegistrosCubit._generation`.
+  int _generation = 0;
+
+  /// `EntryDetailScreen`'s one driver, called from the `GoRoute.builder`
+  /// cascade (Code Map: `sl<EntryDetailCubit>()..load(...)`) — [id] is
+  /// either a real server id or a still-pending/failed placeholder's
+  /// synthetic `tempId` (Boundaries: "un-special-cased navigation target");
+  /// both are simply passed straight through to [EntriesRepository.
+  /// getById] with no branching here.
+  Future<void> load(String id) async {
+    final generation = ++_generation;
+    emit(const EntryDetailLoading());
+    final result = await _repository.getById(id);
+    if (isClosed || generation != _generation) {
+      return;
+    }
+    result.match(
+      (failure) {
+        if (failure is NotFound) {
+          emit(const EntryDetailNotFound());
+          return;
+        }
+        // Boundaries: every other non-absorbed Failure renders the exact
+        // same generic not-found treatment `EntryDetailScreen` gives
+        // EntryDetailNotFound — kept as its own state only for a test's
+        // sake (entry_detail_state.dart's own doc).
+        emit(EntryDetailError(message: failure.message));
+      },
+      (entry) {
+        PendingEntryWrite? matchingPending;
+        for (final pending in _pendingWrites) {
+          if (pending.tempId == entry.id) {
+            matchingPending = pending;
+            break;
+          }
+        }
+        emit(
+          EntryDetailData(
+            entry: entry,
+            badgeState: deriveSyncBadgeState(entry, matchingPending),
+          ),
+        );
+      },
+    );
+  }
+
+  @override
+  Future<void> close() async {
+    await _pendingSubscription.cancel();
+    await _sessionSubscription.cancel();
+    return super.close();
+  }
+}
diff --git a/lib/features/entries/presentation/cubit/entry_detail_state.dart b/lib/features/entries/presentation/cubit/entry_detail_state.dart
new file mode 100644
index 0000000..614cba8
--- /dev/null
+++ b/lib/features/entries/presentation/cubit/entry_detail_state.dart
@@ -0,0 +1,82 @@
+import '../../domain/entities/entry.dart';
+import '../../domain/entities/sync_badge_state.dart';
+
+/// `EntryDetailScreen`'s own sealed state (spec-4-4, Code Map) — mirrors
+/// `MeusRegistrosState`'s shape (a loading/resolved/empty-ish/error split),
+/// never the shared `Resource<T>` (same exclusion rationale
+/// `MeusRegistrosState`'s own doc already gives): this screen's one-shot
+/// fetch still has its own distinct "not found" outcome `Resource<T>`
+/// doesn't model.
+sealed class EntryDetailState {
+  const EntryDetailState();
+}
+
+/// The one `EntriesRepository.getById` fetch is in flight — `EntryDetail
+/// Screen` renders nothing below this (no skeleton of its own; this
+/// screen has no prototype precedent to match, Intent).
+class EntryDetailLoading extends EntryDetailState {
+  const EntryDetailLoading();
+}
+
+/// The fetch resolved to a real [Entry] — [badgeState] is always
+/// [SyncBadgeState.synchronized] in practice (Boundaries: "a fetched Entry
+/// is always server-confirmed"), still derived through the one shared
+/// `deriveSyncBadgeState()` rather than hardcoded here (Never: "a second
+/// sync-badge derivation path").
+class EntryDetailData extends EntryDetailState {
+  const EntryDetailData({required this.entry, required this.badgeState});
+
+  final Entry entry;
+  final SyncBadgeState badgeState;
+
+  @override
+  bool operator ==(Object other) =>
+      identical(this, other) ||
+      (other is EntryDetailData &&
+          other.entry == entry &&
+          other.badgeState == badgeState);
+
+  @override
+  int get hashCode => Object.hash(entry, badgeState);
+
+  @override
+  String toString() =>
+      'EntryDetailData(entry: ${entry.id}, badgeState: $badgeState)';
+}
+
+/// `Failure.notFound` specifically — an id that never existed or belongs
+/// to another user (RNF04). Kept as its own sealed variant purely so a
+/// test can assert exactly which `Failure` produced a given outcome;
+/// `EntryDetailScreen` renders this identically to [EntryDetailError]
+/// (RNF04's "never a distinguishable permission-denied state" extends
+/// here to "never a distinguishable failure-reason state" either, Code
+/// Map) — the two variants never look different on screen.
+class EntryDetailNotFound extends EntryDetailState {
+  const EntryDetailNotFound();
+}
+
+/// Every other `Failure` this screen's fetch can surface that the
+/// repository's own offline/timeout cache fallback doesn't absorb (e.g. a
+/// cache-miss `networkOffline`/`networkTimeout`, or any backend code the
+/// fallback never intercepts) — Boundaries: "`Failure.notFound` (and any
+/// other failure the cache doesn't absorb) renders one generic not-found
+/// treatment". [message] is [Failure.message] verbatim (same convention
+/// `MeusRegistrosError.message` already uses) but is never actually
+/// surfaced as screen copy — kept only for this state's own equality/
+/// toString and tests.
